			const uint8_t *fragment = p_body.ptr();

			int local_name_len = decode_uint16(fragment + 26);
			int local_extra_len = decode_uint16(fragment + 28);
			int full_file_chunk_size = 30 + local_name_len + local_extra_len + file_info.compressed_size;

			if (p_body.size() < full_file_chunk_size) {
				print_line(vformat("[ERROR] Fragment too small! Loaded: %d, Required: %d", p_body.size(), full_file_chunk_size));
				return;
			}

			// Without mini zip
			//++++++++++++++++++++++++++++++++++++++++++++++++++++++
			int data_start = 30 + local_name_len + local_extra_len;
			int compressed_size = file_info.compressed_size;
			int uncompressed_size = file_info.uncompressed_size;

			PackedByteArray compressed_payload = p_body.slice(data_start, data_start + compressed_size);
			PackedByteArray decompressed_data;
			decompressed_data.resize(uncompressed_size);

			int result = Compression::decompress(
				decompressed_data.ptrw(),
				uncompressed_size,
				compressed_payload.ptr(),
				compressed_size,
				Compression::MODE_DEFLATE_RAW
			);

			if (result < 0) {
				print_line("[ERROR] Decompression failed!");
			}

